function updateTrafficUI(){
 const stats=traffic.stats();$('#traffic-network').textContent=`${stats.roads} 格连通道路 · ${stats.junctions} 处信号路口`;
 $('#traffic-flow').textContent=stats.active?stats.flow:'—';$('#traffic-active').textContent=stats.active;$('#traffic-waiting').textContent=stats.waiting;$('#traffic-completed').textContent=stats.completed;
 $('#traffic-note').textContent=traffic.targetCount?`抽样出行 · ${stats.pending} 辆等待驶出 · 平均行程 ${Math.round(stats.averageTrip)} 模拟秒。路口红灯会降低实时效率。`:'暂无出行需求：请让有居民的住宅与商业、工业或公园通过道路相连。';
 const car=traffic.vehicles.find(c=>c.id===followedCar&&c.state==='moving');
 $('#traffic-trip').textContent=car?`车辆 ${String(car.id).padStart(2,'0')} · ${car.returning?'返家':car.purpose} · ${car.speed<.08?'正在等候':`驶向 ${car.destination%SIZE+1}:${Math.floor(car.destination/SIZE)+1}`} · 剩余 ${car.path.length-car.index} 格`:'选择跟随，在自己的街区里转一圈。';
 const hotspots=[...traffic.nodes.keys()].map(id=>({id,...traffic.roadStats(id)})).filter(s=>s.waiting||s.delay>.2).sort((a,b)=>b.waiting-a.waiting||b.delay-a.delay).slice(0,3);
 $('#traffic-hotspots').innerHTML=hotspots.length?hotspots.map(s=>`<button data-traffic-road="${s.id}"><span>${s.id%SIZE+1} : ${Math.floor(s.id/SIZE)+1}</span><b>${s.waiting?`${s.waiting} 辆等待`:'近期缓行'}</b><i>↗</i></button>`).join(''):'<p>暂时顺畅。可开启图层观察路口。</p>';
 const roadInfo=$('#road-traffic');if(roadInfo&&selectedCell?.type==='road'){const s=traffic.roadStats(selectedCell.z*SIZE+selectedCell.x);roadInfo.textContent=`车流 ${s.vehicles} 辆 · 等待 ${s.waiting} 辆 · 已通过 ${s.passed} 次${s.signal==='none'?'':' · 信号路口'}`;}
}
