window.addEventListener('resize',()=>{renderer.setSize(innerWidth,innerHeight);pipeline?.setSize(innerWidth,innerHeight);updateCamera()});window.addEventListener('beforeunload',()=>sim.save());
updateUI();setTool('inspect');document.querySelectorAll('[data-speed]').forEach(b=>b.classList.toggle('active',Number(b.dataset.speed)===sim.speed));

const streetLights=[];for(const [x,z] of [[5,17],[10,17],[15,17],[20,17],[25,17],[30,17]]){const l=new THREE.PointLight('#ffd092',0,3.4,2);l.position.set(x+.35,.78,z+.32);l.userData.tile={x,z};scene.add(l);streetLights.push(l);}
let perfLast=performance.now(),perfWindow=performance.now(),perfFrames=0,displayFps=0;
function updateStreetLights(night){for(const l of streetLights){const c=sim.cell(l.userData.tile.x,l.userData.tile.z);l.intensity=c?.type==='road'&&c.connected?night*2.7:0;}}
function persistGraphics(){try{localStorage.setItem('pixel-bay-graphics-v2',JSON.stringify(graphics))}catch{}}
function applyGraphics(){
 const p=lighting.setTime(solarHour,graphics.realistic);setMaterialLighting({night:graphics.realistic?p.night:0,wetness:graphics.realistic?p.wetness:0});
 updateStreetLights(graphics.realistic?p.night:0);setDesignerLighting({night:graphics.realistic?p.night:0,wetness:graphics.realistic?p.wetness:0});
 pipeline.setQuality(graphics.quality);pipeline.setOptions({enabled:graphics.realistic,temporal:graphics.temporal,ao:graphics.ao?.95:0,gi:graphics.ao?.65:0,bloom:graphics.bloom?.8:0,sharpen:.48,exposure:p.exposure});
 physicalWater.setQuality(graphics.quality);physicalWater.setEnabled(graphics.realistic&&graphics.reflections);
 for(const m of materialCache.values()){if(m.userData.surface==='asphalt'){m.roughness=graphics.realistic?.85-p.wetness*.68:1;m.clearcoat=graphics.realistic?.12+p.wetness*.7:0;}if(m.emissive.getHex()!==0)m.emissiveIntensity=graphics.realistic?.25+p.night*2:0;}
 document.body.classList.toggle('realistic',graphics.realistic);document.body.dataset.light=graphics.preset;
 $('#light-label').textContent=graphics.realistic?`${p.time} · ${p.label}`:'基础光照';
 $('#render-label').textContent=graphics.realistic?'写实光影':'基础光照';
 $('#scene-time').innerHTML=`<i class="sun"></i>${graphics.realistic?p.label:'春日'} · 晴`;
 updateCamera();pipeline.resetHistory();persistGraphics();
}
function updateRenderStatus(now){
 perfFrames++;if(now-perfWindow>1000){displayFps=Math.round(perfFrames*1000/(now-perfWindow));perfFrames=0;perfWindow=now;const info=pipeline.getInfo();$('#render-fps').textContent=`${displayFps} FPS`;const meter=$('#graphics-meter');if(meter)meter.textContent=`${info.width||'—'} × ${info.height||'—'} 渲染 · ${displayFps} FPS`;}
}
function showGraphics(){
 const qualityLabels={performance:'流畅',balanced:'均衡',high:'精细'};
 modal('让光，照进这座城。',`<p>保留像素轮廓，观察光线在玻璃、石材与河面上的真实变化。</p>
 <div class="graphics-section"><label>光照时刻</label><div class="graphics-segments">${Object.entries(LIGHT_PRESETS).map(([key,p])=>`<button data-light="${key}" class="${graphics.preset===key?'active':''}"><b>${p.time}</b><span>${p.label}</span></button>`).join('')}</div></div>
 <div class="day-cycle-controls"><label><input type="checkbox" id="day-cycle" ${dayCycle?'checked':''}> 连续昼夜循环</label><span>10 分钟 / 日</span></div><label class="solar-time-control" for="solar-slider">时刻 <span id="solar-hour">${String(Math.floor(solarHour)).padStart(2,'0')}:${String(Math.floor(solarHour%1*60)).padStart(2,'0')}</span><input type="range" id="solar-slider" min="0" max="23.99" step="0.01" value="${solarHour}"></label><div class="graphics-section"><label>画质与性能 <span id="graphics-meter">正在采样帧率</span></label><div class="graphics-segments quality">${Object.entries(qualityLabels).map(([key,label])=>`<button data-quality="${key}" class="${graphics.quality===key?'active':''}">${label}<small>${{performance:'较低内部像素 · 重建',balanced:'均衡内部像素 · 重建',high:'精细采样 · 重建'}[key]}</small></button>`).join('')}</div></div>
 <div class="graphics-switches">${[['realistic','写实光影','物理材质、天空照明与电影色调'],['temporal','时域超采样重建','多帧采样 + 历史重投影，稳定细小边缘'],['ao','接触阴影与间接光','增强楼宇、街道与树木的空间关系'],['reflections','河面真实反射','镜像相机渲染 + Fresnel 水面反射'],['bloom','柔和高光','保留亮部细节，轻微扩散窗灯与日光']].map(([key,title,desc])=>`<label class="graphics-switch"><div><b>${title}</b><small>${desc}</small></div><input type="checkbox" data-graphics="${key}" ${graphics[key]?'checked':''}><span class="switch-track"></span></label>`).join('')}</div>
 <p class="graphics-note">浏览器混合渲染实验：PBR、平面反射、屏幕空间间接光与时域重建。不是完整路径追踪，也不使用 NVIDIA DLSS。</p><div class="modal-footer"><button class="primary-button" id="graphics-done">回到城市 →</button></div>`);
 $('#graphics-done').onclick=closeModal;$('#day-cycle').onchange=e=>{dayCycle=e.target.checked;};$('#solar-slider').oninput=e=>{solarHour=Number(e.target.value);dayCycle=false;$('#day-cycle').checked=false;updateEnvironment(0,true);$('#solar-hour').textContent=solarTimeLabel();};
 $('#modal-content').querySelectorAll('button[data-light]').forEach(b=>b.onclick=()=>{graphics.preset=b.dataset.light;solarHour={morning:8.5,golden:17.5,blue:19.25}[graphics.preset];dayCycle=false;graphics.realistic=true;applyGraphics();$('#day-cycle').checked=false;$('#solar-slider').value=solarHour;$('#solar-hour').textContent=solarTimeLabel();$('#modal-content').querySelectorAll('button[data-light]').forEach(x=>x.classList.toggle('active',x===b));$('[data-graphics="realistic"]').checked=true;});
 document.querySelectorAll('[data-quality]').forEach(b=>b.onclick=()=>{graphics.quality=b.dataset.quality;applyGraphics();document.querySelectorAll('[data-quality]').forEach(x=>x.classList.toggle('active',x===b));});
 document.querySelectorAll('[data-graphics]').forEach(b=>b.onchange=()=>{graphics[b.dataset.graphics]=b.checked;applyGraphics();});
}
$('#graphics-btn').innerHTML=icon('camera');$('#graphics-btn').onclick=showGraphics;$('#light-chip').onclick=showGraphics;
applyGraphics();
function updateEditButtons(){if($('#undo-btn'))$('#undo-btn').disabled=!sim.canUndo;if($('#redo-btn'))$('#redo-btn').disabled=!sim.canRedo;}
function performEdit(action){cancelGesture();const r=sim[action]();toast(r.message,!r.ok);if(r.changed){buildDirty=true;selectedCell=null;$('#inspection').classList.add('hidden');updateUI();updateEditButtons();}}
function restoreCity(data){const previousCity=sim.exportState();const r=sim.importState(data);toast(r.message,!r.ok);if(r.ok){try{localStorage.setItem('pixel-bay-before-import',JSON.stringify(previousCity));}catch{}document.querySelectorAll('[data-speed]').forEach(b=>b.classList.toggle('active',Number(b.dataset.speed)===sim.speed));selectedCell=null;$('#inspection').classList.add('hidden');buildDirty=true;traffic.reset();stopFollowing();oldPopulation=sim.population;accumulator=0;updateUI();updateEditButtons();closeModal();}}
function showArchives(){
 let slots=[];try{const v=JSON.parse(localStorage.getItem('pixel-bay-slots-v1')||'[]');if(Array.isArray(v))slots=v.slice(0,3);}catch{}
 modal('每一座城，都值得留下。',`<p>自动存档保留当前城市。另存为城市档案，或导出文件备份与分享。</p><div class="archive-slots">${Array.from({length:3},(_,i)=>{const item=slots[i];return `<div class="archive-slot"><div><b>城市档案 ${String(i+1).padStart(2,'0')}</b><small>${item?`${escText(item.population||0)} 位居民 · 第 ${escText(item.day||1)} 天<br>${escText(item.time||'')}`:'空档案 · 等待一座新城'}</small></div><button data-save-slot="${i}">${item?'覆盖保存':'存入城市'}</button>${item?`<button data-load-slot="${i}">载入</button>`:''}</div>`}).join('')}</div><div class="archive-file-actions"><button id="export-city" class="secondary-button">导出城市 JSON</button><button id="import-city" class="secondary-button">导入城市 JSON</button><input type="file" accept=".json,application/json" id="city-file" hidden></div><p class="graphics-note">档案与蓝图保存在此浏览器。导出文件可跨设备迁移。载入前会在本地保留一份恢复备份。</p><div class="modal-footer"><button class="primary-button" id="archives-done">回到城市</button><button class="secondary-button" id="restore-backup">恢复载入前备份</button></div>`);
 $('#archives-done').onclick=closeModal;$('#export-city').onclick=()=>downloadJSON(sim.exportState(),'pixel-bay-city.json');
 document.querySelectorAll('[data-save-slot]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.saveSlot);const store=()=>{slots[i]={time:new Date().toLocaleString('zh-CN',{timeZone:'Asia/Singapore'}),population:sim.population,day:sim.day,data:sim.exportState()};try{localStorage.setItem('pixel-bay-slots-v1',JSON.stringify(slots));toast('城市档案已保存');showArchives()}catch{toast('浏览器存储不足，请导出城市文件。',true)}};if(slots[i]){modal('覆盖这份城市档案？','<p>当前城市将写入这个档位。</p><div class="modal-footer"><button id="confirm-slot" class="primary-button">覆盖保存</button><button id="cancel-slot" class="secondary-button">取消</button></div>');$('#confirm-slot').onclick=store;$('#cancel-slot').onclick=showArchives;}else store();});
 const confirmLoad=(data)=>{modal('载入这座城市？','<p>当前城市会先保留恢复备份，再切换到选中的档案。</p><div class="modal-footer"><button id="confirm-load" class="primary-button">载入城市</button><button id="cancel-load" class="secondary-button">保留当前城市</button></div>');$('#confirm-load').onclick=()=>restoreCity(data);$('#cancel-load').onclick=showArchives;};
 document.querySelectorAll('[data-load-slot]').forEach(b=>b.onclick=()=>confirmLoad(slots[Number(b.dataset.loadSlot)].data));
 const file=$('#city-file');$('#import-city').onclick=()=>file.click();file.onchange=async()=>{const f=file.files?.[0];file.value='';if(!f)return;try{if(f.size>2000000)throw new Error('城市文件过大');const data=JSON.parse(await f.text());confirmLoad(data)}catch{toast('无法读取城市文件，请检查 JSON 格式。',true)}};
 $('#restore-backup').onclick=()=>{try{const data=JSON.parse(localStorage.getItem('pixel-bay-before-import')||'null');if(!data){toast('还没有恢复备份');return}confirmLoad(data)}catch{toast('恢复备份不可用',true)}};
}
function escText(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function showTerrain(){modal('让地形，为你的城市让路。','<p>第一阶段提供基础水域编辑：在空地开挖水体，或将河面填为可建设土地。已占用地块需要先拆除。</p><div class="terrain-options"><button id="terrain-land"><b>▧ 填海造陆</b><span>水域 → 陆地 · ₵80 / 格</span></button><button id="terrain-water"><b>≈ 开挖水域</b><span>陆地 → 水域 · ₵50 / 格</span></button></div><p class="graphics-note">地形改动支持撤销与重做。道路仍可跨水自动建桥。</p>');for(const type of ['land','water'])$('#terrain-'+type).onclick=()=>{setTool('inspect');terrainTool=type;$('#tool-name').textContent=type==='land'?'填海造陆':'开挖水域';$('#tool-desc').textContent='点击空闲地块 · 可撤销';$('#tool-cost').textContent=`₵ ${type==='land'?80:50} / 格`;closeModal();toast('地形工具已选择，点击地图开始编辑。')};}
studio=new BuildStudio({scene,onSelect:d=>{setTool(BUILDINGS[d.catalogId].baseType,d);},onMessage:toast});
studio.onPause=on=>{if(on){studioWasPaused=paused;paused=true;keys.clear();cancelGesture();}else paused=studioWasPaused;};
$('#catalog-btn').onclick=()=>{toggleTraffic(false);studio.toggleCatalog();};$('#studio-btn').onclick=()=>studio.open(activeDesign);$('#terrain-btn').onclick=showTerrain;$('#undo-btn').onclick=()=>performEdit('undo');$('#redo-btn').onclick=()=>performEdit('redo');$('#archives-btn').onclick=showArchives;
$('#traffic-btn').onclick=()=>toggleTraffic();$('#traffic-close').onclick=()=>toggleTraffic(false);
$('#traffic-overlay').onchange=e=>trafficView.setOverlay(e.target.checked);$('#traffic-follow').onclick=()=>followTraffic();$('#traffic-next').onclick=()=>followTraffic(true);
$('#traffic-hotspots').onclick=e=>{const b=e.target.closest('[data-traffic-road]');if(!b)return;const c=sim.cells[Number(b.dataset.trafficRoad)];setTool('inspect');target.set(c.x,0,c.z);zoom=Math.max(zoom,1.8);updateCamera();inspect(c);};
updateEditButtons();updateTrafficUI();

function solarTimeLabel(){return `${String(Math.floor(solarHour)).padStart(2,'0')}:${String(Math.floor((solarHour%1)*60)).padStart(2,'0')}`;}
function updateEnvironment(dt,force=false){if(dayCycle&&!paused)solarHour=(solarHour+dt*24/600)%24;environmentTick+=dt;if(!force&&environmentTick<.25)return;environmentTick=0;if(!graphics.realistic)return;const p=lighting.setTime(solarHour,true);pipeline.setOptions({exposure:p.exposure});setMaterialLighting({night:p.night,wetness:p.wetness});setDesignerLighting({night:p.night,wetness:p.wetness});updateStreetLights(p.night);for(const m of materialCache.values()){if(m.userData.surface==='asphalt'){m.roughness=.85-p.wetness*.68;m.clearcoat=.12+p.wetness*.7;}if(m.emissive.getHex()!==0)m.emissiveIntensity=.25+p.night*2;}$('#light-label').textContent=`${solarTimeLabel()} · ${p.label}`;$('#scene-time').innerHTML=`<i class="sun"></i>${p.label} · 晴`;if(force)pipeline.resetHistory();}
let previous=performance.now(),accumulator=0,oldPopulation=sim.population,frameCount=0;function frame(now){requestAnimationFrame(frame);const dt=Math.min(.08,(now-previous)/1000);previous=now;const f=dt*7/zoom;if(keys.has('w')||keys.has('arrowup'))moveCamera(-Math.sin(yaw)*f,-Math.cos(yaw)*f);if(keys.has('s')||keys.has('arrowdown'))moveCamera(Math.sin(yaw)*f,Math.cos(yaw)*f);if(keys.has('a')||keys.has('arrowleft'))moveCamera(-Math.cos(yaw)*f,Math.sin(yaw)*f);if(keys.has('d')||keys.has('arrowright'))moveCamera(Math.cos(yaw)*f,-Math.sin(yaw)*f);if(!paused){accumulator+=dt*sim.speed;if(accumulator>=8){accumulator-=8;const milestone=sim.milestone;sim.tick();if(sim.milestone>milestone){toast('✦ 达成城市里程碑！奖励已存入城市账户。');ding()}$('#growth').textContent=sim.population>oldPopulation?`+${sim.population-oldPopulation} 位新邻居`:'每个家，都有新的故事';oldPopulation=sim.population;updateUI();buildDirty=true}}if(buildDirty){if(geometryKey()!==renderedGeometry)rebuildCity();buildDirty=false}animateCars(dt);updateEnvironment(dt);if(!paused)rotors.forEach(r=>r.rotation.z-=dt*1.4*sim.speed);physicalWater.update(dt,{sunDirection:lighting.sunDirection,sunColor:lighting.sunColor,skyColor:lighting.skyColor,paused,enabled:graphics.realistic&&graphics.reflections});physicalWater.renderReflection();if(now-lastSave>20000)save();pipeline.render(dt);updateRenderStatus(now);if(frameCount++===2){$('#loading').style.opacity='0';setTimeout(()=>$('#loading').remove(),550)}}requestAnimationFrame(frame);
// Exposed read-only diagnostics for local inspection, with all gameplay driven by UI.
window.pixelBay={get stats(){return sim.getStats()},get rendererInfo(){return renderer.info.render},get graphics(){return {...graphics,...pipeline.getInfo()}}};
